class Solution {
public:
    vector<int> distributeCandies(int candies, int num_people) {
        vector<int> res(num_people, 0);
        int give = 1, p = 0;
        while (candies > 0) {
            int g = min(give, candies);
            res[p] += g;
            candies -= g;
            give++;
            p = (p + 1) % num_people;
        }
        return res;
    }
};
